def transform(grid):
    h, w = len(grid), len(grid[0])
    counts = {}
    for row in grid:
        for value in row:
            counts[value] = counts.get(value, 0) + 1
    bg = max(counts, key=counts.get)
    cells = {(r, c): v for r, row in enumerate(grid) for c, v in enumerate(row) if v != bg}
    remaining = set(cells)
    components = []
    while remaining:
        start = remaining.pop()
        stack = [start]
        component = [start]
        while stack:
            r, c = stack.pop()
            for q in ((r - 1, c), (r + 1, c), (r, c - 1), (r, c + 1)):
                if q in remaining:
                    remaining.remove(q)
                    stack.append(q)
                    component.append(q)
        components.append(component)
    stencil = max(components, key=len)
    stencil_set = set(stencil)
    markers = [p for p in cells if p not in stencil_set]
    r0, r1 = min(r for r, c in stencil), max(r for r, c in stencil)
    c0, c1 = min(c for r, c in stencil), max(c for r, c in stencil)
    anchor_r, anchor_c = (r0 + r1) // 2, (c0 + c1) // 2
    shape = [(r - anchor_r, c - anchor_c, cells[(r, c)]) for r, c in stencil]
    out = [row[:] for row in grid]
    for mr, mc in markers:
        for dr, dc, color in shape:
            rr, cc = mr + dr, mc + dc
            if 0 <= rr < h and 0 <= cc < w:
                out[rr][cc] = color
    return out
